using System;
using System.IO;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using CashflowChains.Economy;
using CashflowChains.Empire;
using CashflowChains.Engagement;
public sealed class InvestorRewardsTests {
 BalanceConfig c;const long At=1728000;
 [SetUp]public void Setup(){c=JsonUtility.FromJson<BalanceConfig>(File.ReadAllText(Path.Combine(Application.dataPath,"_Game/Data/CC2/balance-v1.json")));c.Validate();}
 EmpireEngine New(Func<EmpireAccount,bool> save=null){var e=new EmpireEngine(c,new EmpireAccount{Economy=new EconomyState{AccountId="investor-rewards"}},save??(_=>true));e.OpenCity(At);e.EnterExistingCity(At);e.EnterMetropolis(At);e.OpenInvestorRewards(At);return e;}
 void FirstAsset(EmpireEngine e){e.AcquireCityProperty("rental-deed",12027,At+1);e.AdvanceCityTo(At+4);}
 [Test]public void DailyVisitIsOneClaimPerUtcDateAndMissingDaysNeverResetsTheCalendar(){var e=New();e.ClaimInvestorDaily(At+1);long cash=e.Snapshot.Economy.Amount("CASH");e.ClaimInvestorDaily(At+2);Assert.AreEqual(cash,e.Snapshot.Economy.Amount("CASH"));Assert.AreEqual(1,e.Snapshot.Investor.Claims.Count);e.ClaimInvestorDaily(At+4*86400);Assert.AreEqual(1,e.Snapshot.Investor.Claims.Last().Index);Assert.AreEqual("WOOD",e.Snapshot.Investor.Claims.Last().Items.Single().ItemId);e.Snapshot.Validate(c);}
 [Test]public void PaidCalendarCannotReplaceOrGateTheFreeDelivery(){var e=New();Assert.Throws<InvalidOperationException>(()=>e.ClaimInvestorDailyPremium(At/86400,At+1));e.ClaimInvestorDaily(At+2);Assert.Throws<InvalidOperationException>(()=>e.ClaimInvestorDailyPremium(At/86400,At+3));Assert.AreEqual(210,e.Snapshot.Economy.Amount("CASH"));}
 [Test]public void RealAcquisitionAndProfitableDaysProgressOneSeasonOnlyOnceWithCaps(){var e=New();Assert.AreEqual(0,e.Snapshot.Investor.Xp(0));FirstAsset(e);Assert.AreEqual(30,e.Snapshot.Investor.Xp(0));e.AdvanceCityTo(At+5000);var before=e.Snapshot.Investor;Assert.AreEqual(5,before.Activity.Count(x=>x.Kind=="profit"));Assert.AreEqual(80,before.Xp(0));e.AdvanceCityTo(At+5000);Assert.AreEqual(before.Xp(0),e.Snapshot.Investor.Xp(0));Assert.AreEqual(1,before.Activity.Count(x=>x.Kind=="acquisition"));}
 [Test]public void MilestoneUsesActualCareerAndPersistsAReceipt(){var e=New();Assert.Throws<InvalidOperationException>(()=>e.ClaimInvestorMilestone(0,false,At));FirstAsset(e);e.ClaimInvestorMilestone(0,false,At+5);var prior=e.Snapshot;e.ClaimInvestorMilestone(0,false,At+6);Assert.AreEqual(prior.Economy.Amount("CASH"),e.Snapshot.Economy.Amount("CASH"));Assert.AreEqual(1,e.Snapshot.Investor.Claims.Count);var restored=JsonUtility.FromJson<EmpireAccount>(JsonUtility.ToJson(e.Snapshot));restored.Validate(c);Assert.AreEqual(1,restored.Investor.Claims.Count);}
 [Test]public void FreeSeasonEarnedRewardsRemainClaimableAfterTheRealSeasonEnds(){var e=New();FirstAsset(e);Assert.Throws<InvalidOperationException>(()=>e.ClaimInvestorSeason(0,1,false,At+5));e.ClaimInvestorSeason(0,0,false,At+29*86400);Assert.AreEqual(1,e.Snapshot.Investor.Claims.Count);Assert.AreEqual(30,e.Snapshot.Investor.Xp(0));Assert.AreEqual(0,e.Snapshot.Investor.Xp(1));Assert.Throws<InvalidOperationException>(()=>e.ClaimInvestorSeason(1,0,false,At+29*86400));}
 [Test]public void VerifiedGrowthAndDailyOwnershipGrantRetroactiveExtrasWithoutRegrantingFreeRewards(){var e=New();FirstAsset(e);e.ClaimInvestorDaily(At+5);e.ClaimInvestorMilestone(0,false,At+5);e.FulfillVerifiedInvestorPurchase(new string('a',64),"cc2.growthfund",0,At+6);e.FulfillVerifiedInvestorPurchase(new string('b',64),"cc2.investorclub",0,At+6);e.ClaimInvestorMilestone(0,true,At+7);e.ClaimInvestorDailyPremium(At/86400,At+7);var prior=e.Snapshot;e.ClaimInvestorDailyPremium(At/86400,At+8);Assert.AreEqual(prior.Economy.Amount("CASH"),e.Snapshot.Economy.Amount("CASH"));Assert.AreEqual(4,e.Snapshot.Investor.Claims.Count);Assert.Throws<InvalidOperationException>(()=>e.FulfillVerifiedInvestorPurchase(new string('c',64),"cc2.growthfund",0,At+9));}
 [Test]public void VerifiedTokenCannotGrantDifferentProductsOrDuplicateItsPack(){var e=New();FirstAsset(e);string token=new string('a',64);e.FulfillVerifiedInvestorPurchase(token,"cc2.starter",0,At+5);long cash=e.Snapshot.Economy.Amount("CASH");e.FulfillVerifiedInvestorPurchase(token,"cc2.starter",0,At+6);Assert.AreEqual(cash,e.Snapshot.Economy.Amount("CASH"));Assert.Throws<InvalidOperationException>(()=>e.FulfillVerifiedInvestorPurchase(token,"cc2.growthfund",0,At+7));}
 [Test]public void UnavailableAndMalformedPremiumActionsFailWithoutChangingTheWallet(){var e=New();Assert.Throws<InvalidOperationException>(()=>e.FulfillVerifiedInvestorPurchase(new string('a',64),"cc2.starter",0,At+1));Assert.Throws<ArgumentException>(()=>e.FulfillVerifiedInvestorPurchase("not-a-receipt","cc2.starter",0,At+1));Assert.Throws<ArgumentException>(()=>e.ClaimInvestorMilestone(99,false,At+1));Assert.Throws<InvalidOperationException>(()=>e.ClaimInvestorSeason(0,0,true,At+1));Assert.AreEqual(200,e.Snapshot.Economy.Amount("CASH"));}
 [Test]public void EarnedChestCommitsOneDisclosedOutcomeAndCannotBeReopenedByRetry(){var e=New();FirstAsset(e);e.AdvanceCityTo(At+10);e.ClaimInvestorMilestone(1,false,At+11);e.OpenInvestorChest("earned-chest-1",At+12);var before=e.Snapshot;var reward=before.Investor.Claims.Last();Assert.AreEqual("chest",reward.Kind);Assert.IsTrue(c.Investor.Bronze.Any(x=>x.Items.Single().ItemId==reward.Items.Single().ItemId&&x.Items.Single().Quantity==reward.Items.Single().Quantity));Assert.AreEqual(0,before.Economy.Amount("CHEST:bronze"));e.OpenInvestorChest("earned-chest-1",At+13);Assert.AreEqual(before.Economy.Revision,e.Snapshot.Economy.Revision);Assert.Throws<InvalidOperationException>(()=>e.OpenInvestorChest("empty-chest",At+14));}
 [Test]public void FailedDurableSaveDoesNotLoseAClaimOrItsReward(){bool working=true;var e=New(_=>working);working=false;Assert.Throws<InvalidOperationException>(()=>e.ClaimInvestorDaily(At+1));Assert.AreEqual(200,e.Snapshot.Economy.Amount("CASH"));Assert.IsEmpty(e.Snapshot.Investor.Claims);working=true;e.ClaimInvestorDaily(At+2);Assert.AreEqual(210,e.Snapshot.Economy.Amount("CASH"));}
 [Test]public void ForgedRewardProjectionAndXpCapsAreRejected(){var e=New();e.ClaimInvestorDaily(At+1);var broken=e.Snapshot;broken.Investor.Claims[0].Items[0].Quantity++;Assert.Throws<ArgumentException>(()=>broken.Validate(c));broken=e.Snapshot;broken.Investor.Claims[0].Index=100;Assert.Throws<ArgumentException>(()=>broken.Validate(c));broken=e.Snapshot;broken.Investor=null;Assert.Throws<ArgumentException>(()=>broken.Validate(c));FirstAssetAfterClaim(e);broken=e.Snapshot;broken.Investor.Activity[0].Xp=101;Assert.Throws<ArgumentException>(()=>broken.Validate(c));}
 void FirstAssetAfterClaim(EmpireEngine e){e.AcquireCityProperty("first",12027,At+2);e.AdvanceCityTo(At+5);}
 [Test]public void VerifiedSeasonPassIsBoundToItsSeasonAndUnlocksAlreadyEarnedTiers(){var e=New();FirstAsset(e);e.AcquireCityProperty("second-asset",12028,At+5);e.AdvanceCityTo(At+8);e.ClaimInvestorSeason(0,0,false,At+9);e.FulfillVerifiedInvestorPurchase(new string('c',64),"cc2.seasonpass",0,At+10);e.ClaimInvestorSeason(0,0,true,At+11);var prior=e.Snapshot;e.ClaimInvestorSeason(0,0,true,At+12);Assert.AreEqual(prior.Economy.Revision,e.Snapshot.Economy.Revision);Assert.Throws<InvalidOperationException>(()=>e.FulfillVerifiedInvestorPurchase(new string('d',64),"cc2.seasonpass",0,At+13));Assert.Throws<InvalidOperationException>(()=>e.FulfillVerifiedInvestorPurchase(new string('e',64),"cc2.seasonpass",0,At+29*86400));e.FulfillVerifiedInvestorPurchase(new string('f',64),"cc2.seasonpass",1,At+29*86400);Assert.IsTrue(e.Snapshot.Investor.Owns("season",1,c.Investor));Assert.AreEqual(2,e.Snapshot.Investor.Claims.Count);}
 [Test]public void AuthoredChanceTableHasExactDistributionAndNoHiddenOutcome(){int[] frequencies=new int[c.Investor.Bronze.Length];for(int roll=0;roll<10000;roll++)frequencies[c.Investor.BronzeIndex(roll)]++;Assert.Throws<ArgumentOutOfRangeException>(()=>c.Investor.BronzeIndex(-1));Assert.Throws<ArgumentOutOfRangeException>(()=>c.Investor.BronzeIndex(10000));CollectionAssert.AreEqual(c.Investor.Bronze.Select(x=>x.Weight),frequencies);}
}
